INSERT INTO `stories` (`id`, `team_id`, `created_by`, `title`, `slug`, `original_title`, `original_author`, `short_description`, `description`, `cover_url`, `banner_url`, `content_type`, `story_format`, `story_type`, `status`, `progress_status`, `age_rating`, `published_at`, `last_chapter_at`, `view_count_cache`, `follow_count_cache`, `favorite_count_cache`, `recommendation_gem_cache`, `created_at`, `updated_at`) VALUES
    ('11000000-0000-0000-0000-000000000001', '03000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', 'Nắng Qua Lối Cũ', 'nang-qua-loi-cu', 'Nắng Qua Lối Cũ', 'Chưa xác định', 'Truyện đô thị / he / đoản văn do Lavie thực hiện.', '<p><strong>Nắng Qua Lối Cũ</strong> là bản dịch của Lavie.</p><p>Thể loại: Đô Thị, HE, Đoản Văn, Chữa Lành, Gương Vỡ Lại Lành.</p><p>Đây là dữ liệu mẫu dùng cho môi trường phát triển cục bộ.</p>', 'https://cdn.monkeydarchive.com/images/story/2026/08/17/1786939062-nang-qua-loi-cu.jpg', 'https://cdn.monkeydarchive.com/images/story/2026/08/17/1786939062-nang-qua-loi-cu.jpg', 'TEXT', 'ONESHOT', 'TEXT', 'PUBLISHED', 'COMPLETED', '13+', TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 13 DAY, TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 1417 MINUTE, 11, 0, 0, 80, TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 13 DAY, TIMESTAMP('2026-08-17 09:00:00')),
    ('11000000-0000-0000-0000-000000000002', '03000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', 'Hoán Đổi Linh Hồn Cưới Chồng Người Ta', 'hoan-doi-linh-hon-cuoi-chong-nguoi-ta', 'Hoán Đổi Linh Hồn Cưới Chồng Người Ta', 'Lavie', 'Truyện vả mặt / huyền huyễn / hoán đổi thân xác do Lavie thực hiện.', '<p><strong>Hoán Đổi Linh Hồn Cưới Chồng Người Ta</strong> là bản dịch của Lavie.</p><p>Thể loại: Vả Mặt, Huyền Huyễn, Hoán Đổi Thân Xác, Chữa Lành, Xuyên Không, Cưới Trước Yêu Sau, Phép Thuật.</p><p>Đây là dữ liệu mẫu dùng cho môi trường phát triển cục bộ.</p>', 'https://cdn.monkeydarchive.com/images/story/2026/08/15/1786730090-hoan-doi-linh-hon-cuoi-chong-nguoi-ta.jpg', 'https://cdn.monkeydarchive.com/images/story/2026/08/15/1786730090-hoan-doi-linh-hon-cuoi-chong-nguoi-ta.jpg', 'TEXT', 'SERIAL', 'TEXT', 'PUBLISHED', 'ONGOING', '13+', TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 57 DAY, TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 1443 MINUTE, 1119, 1, 0, 40, TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 57 DAY, TIMESTAMP('2026-08-17 09:00:00')),
    ('11000000-0000-0000-0000-000000000003', '03000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', 'Bổn Tiểu Thư Hôm Nay Bệnh Rồi', 'bon-tieu-thu-hom-nay-benh-roi', 'Bổn Tiểu Thư Hôm Nay Bệnh Rồi', 'Lavie', 'Truyện ngôn tình / hệ thống / he do Lavie thực hiện.', '<p><strong>Bổn Tiểu Thư Hôm Nay Bệnh Rồi</strong> là bản dịch của Lavie.</p><p>Thể loại: Ngôn Tình, Hệ Thống, HE, Hiện Đại, Xuyên Sách.</p><p>Đây là dữ liệu mẫu dùng cho môi trường phát triển cục bộ.</p>', 'https://cdn.monkeydarchive.com/images/story/2026/08/16/1786874064-bon-tieu-thu-hom-nay-benh-roi.jpg', 'https://cdn.monkeydarchive.com/images/story/2026/08/16/1786874064-bon-tieu-thu-hom-nay-benh-roi.jpg', 'TEXT', 'SERIAL', 'TEXT', 'PUBLISHED', 'ONGOING', '13+', TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 49 DAY, TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 1493 MINUTE, 129, 2, 0, 60, TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 49 DAY, TIMESTAMP('2026-08-17 09:00:00')),
    ('11000000-0000-0000-0000-000000000004', '03000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', 'Thư Hòa Ly Nơi Kinh Thành Mưa Tuyết', 'thu-hoa-ly-noi-kinh-thanh-mua-tuyet', 'Thư Hòa Ly Nơi Kinh Thành Mưa Tuyết', 'Lạc Hoa Hiên', 'Truyện ngôn tình / cổ đại / ngược do Lạc Hoa Hiên thực hiện.', '<p><strong>Thư Hòa Ly Nơi Kinh Thành Mưa Tuyết</strong> là bản dịch của Lạc Hoa Hiên.</p><p>Thể loại: Ngôn Tình, Cổ Đại, Ngược, Ngọt, Truy Thê, Sảng Văn, Gương Vỡ Không Lành.</p><p>Đây là dữ liệu mẫu dùng cho môi trường phát triển cục bộ.</p>', 'https://cdn.monkeydarchive.com/images/story/2026/08/17/1786937264-thu-hoa-ly-noi-kinh-thanh-mua-tuyet.jpg', 'https://cdn.monkeydarchive.com/images/story/2026/08/17/1786937264-thu-hoa-ly-noi-kinh-thanh-mua-tuyet.jpg', 'TEXT', 'SERIAL', 'TEXT', 'PUBLISHED', 'COMPLETED', '13+', TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 41 DAY, TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 2613 MINUTE, 162, 0, 0, 75, TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 41 DAY, TIMESTAMP('2026-08-17 09:00:00')),
    ('11000000-0000-0000-0000-000000000005', '03000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000002', 'Xuyên Nhanh: Sau Khi Trở Thành Bạch Nguyệt Quang Của Nam Chính, Tôi Thức Tỉnh', 'xuyen-nhanh-sau-khi-tro-thanh-bach-nguyet-quang-cua-nam-chinh-toi-thuc-tinh', 'Xuyên Nhanh: Sau Khi Trở Thành Bạch Nguyệt Quang Của Nam Chính, Tôi Thức Tỉnh', 'Tiệm nhà Dứa', 'Truyện ngôn tình / cổ đại / hệ thống do Tiệm nhà Dứa thực hiện.', '<p><strong>Xuyên Nhanh: Sau Khi Trở Thành Bạch Nguyệt Quang Của Nam Chính, Tôi Thức Tỉnh</strong> là bản dịch của Tiệm nhà Dứa.</p><p>Thể loại: Ngôn Tình, Cổ Đại, Hệ Thống, HE, Hiện Đại, Sủng, Huyền Huyễn, Mạt Thế, Xuyên Không, Dị Năng, Ngọt.</p><p>Đây là dữ liệu mẫu dùng cho môi trường phát triển cục bộ.</p>', 'https://cdn.monkeydarchive.com/images/story/2025/09/25/1758805289-xuyen-nhanh-sau-khi-tro-thanh-bach-nguyet-quang-cua-nam-chinh-toi-thuc-tinh.jpg', 'https://cdn.monkeydarchive.com/images/story/2025/09/25/1758805289-xuyen-nhanh-sau-khi-tro-thanh-bach-nguyet-quang-cua-nam-chinh-toi-thuc-tinh.jpg', 'TEXT', 'SERIAL', 'TEXT', 'PUBLISHED', 'ONGOING', '13+', TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 19 DAY, TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 3514 MINUTE, 304, 20, 5, 37, TIMESTAMP('2026-08-17 09:00:00') - INTERVAL 19 DAY, TIMESTAMP('2026-08-17 09:00:00')),
